from __future__ import annotations

from datetime import datetime
from typing import Literal
from uuid import UUID, uuid4

from pydantic import BaseModel, Field


class JournalEntry(BaseModel):
    """Daily or weekly journal entry for a bot, generated by Reflection agent.

    Contains summary statistics and LLM-generated analysis for a trading period.
    """

    id: UUID = Field(default_factory=uuid4)
    bot_id: UUID
    period_start: datetime
    period_end: datetime
    period_type: Literal["daily", "weekly"]
    content: str
    trade_count: int = Field(ge=0)
    win_rate: float | None = Field(default=None, ge=0.0, le=1.0)
    period_pnl_pct: float | None = None
    generated_at: datetime
    llm_model: str


class ParamChangeProposal(BaseModel):
    """Proposal for a parameter change suggested by the Reflection agent.

    Based on journal analysis, the agent proposes tweaks to strategy parameters
    with rationale. Status tracks whether the proposal is pending research,
    rejected, or in a deeper investigation.
    """

    id: UUID = Field(default_factory=uuid4)
    journal_entry_id: UUID
    strategy_id: str
    parameter: str
    current_value: str
    proposed_value: str
    rationale: str
    status: Literal["proposed", "in_research", "rejected"] = "proposed"
    proposed_at: datetime
